// 1. 匿名管道示例：父子进程通过继承 fd 通信
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <sys/wait.h>

int main() {
    int fd[2];
    if (pipe(fd) == -1) {
        perror("pipe");
        return 1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }

    if (pid == 0) {
        close(fd[0]);
        const char *msg = "Hello from child";
        write(fd[1], msg, strlen(msg));
        close(fd[1]);
        return 0;
    }

    close(fd[1]);
    char buf[100];
    ssize_t n = read(fd[0], buf, sizeof(buf) - 1);
    if (n > 0) {
        buf[n] = '\0';
        printf("Parent received: %s\n", buf);
    }
    close(fd[0]);
    waitpid(pid, NULL, 0);
    return 0;
}

// 2. 共享内存示例（POSIX）：真实工程还要配 sem_open/sem_wait 保护写入
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

int fd = shm_open("/myshm", O_CREAT | O_RDWR, 0600);
ftruncate(fd, 4096);
int *ptr = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
*ptr = 42;
munmap(ptr, 4096);
close(fd);

int fd2 = shm_open("/myshm", O_RDONLY, 0600);
int *ptr2 = mmap(NULL, 4096, PROT_READ, MAP_SHARED, fd2, 0);
printf("Value: %d\n", *ptr2);
munmap(ptr2, 4096);
close(fd2);
shm_unlink("/myshm");
